<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {request} from '../api/client'
import type {components} from '../api/schema'
type ModelSettings=components['schemas']['ModelSettings']
type Settings=components['schemas']['Settings']
const result=ref<Settings|null>(null),value=ref<ModelSettings|null>(null),hosts=ref(''),busy=ref(false),error=ref(''),notice=ref('')
async function load(){try{result.value=await request<Settings>('/diagnostic/settings');value.value=JSON.parse(JSON.stringify(result.value.settings)) as ModelSettings;hosts.value=(value.value.official_hosts??[]).join('\n')}catch(e){error.value=e instanceof Error?e.message:String(e)}}
async function save(){if(!value.value)return;busy.value=true;error.value='';try{result.value=await request<Settings>('/diagnostic/settings',{...value.value,official_hosts:hosts.value.split(/\s+/).filter(Boolean)});value.value=JSON.parse(JSON.stringify(result.value.settings)) as ModelSettings;notice.value='设置已保存。已有资料需重新预览确认。'}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="diag-settings"><p class="alert" v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><article class="panel" v-if="value"><div class="heading"><h2>模型连接</h2><span class="pill">{{result?.available?'可用':'未就绪'}}</span></div><p class="muted">{{result?.reason}}</p><label for="model-mode">模式</label><select id="model-mode" v-model="value.mode"><option value="free">百炼免费模式</option><option value="compatible">兼容接口（自行配置）</option></select><label for="model-base">基础接口地址</label><input id="model-base" v-model="value.base_url" placeholder="兼容模式：https://你的模型服务/v1"><label for="model-name">模型名称</label><input id="model-name" v-model="value.model"><label for="model-key-env">密钥环境变量名</label><input id="model-key-env" v-model="value.key_env"><p class="muted">在本机 .env 或服务进程环境中配置该变量。这里只填写变量名，密钥不保存到浏览器。兼容模式可能产生费用；本机HTTP模型也需配置对应变量。</p><label class="diag-check"><input type="checkbox" v-model="value.enabled">我明确启用新排查流程的此模型配置；兼容模式费用由我自行确认。</label><div class="diag-grid"><div><label for="model-daily">每日请求上限</label><input id="model-daily" v-model.number="value.daily_limit" type="number" min="1" max="200"></div><div><label for="model-output">每次最大输出 Token</label><input id="model-output" v-model.number="value.max_output" type="number" min="256" max="2048"></div></div><p class="muted">今日已预留 {{result?.used_today??0}} 次请求。默认20次、最多2048输出Token；不是精确金额上限。响应或用量未知时不自动重试，不自动切换模型。</p><details><summary>官方文档域名白名单</summary><textarea v-model="hosts" rows="8"></textarea><p class="muted">每行一个完整可信官方域名。仅读取你选择的HTTPS链接，不自动搜索；私网地址和白名单外重定向会被拒绝。</p></details><button class="primary" :disabled="busy" @click="save">保存设置</button></article></div></template>
<style scoped>.diag-settings{display:grid;gap:18px}.diag-settings input:not([type=checkbox]),.diag-settings select{width:100%;padding:11px;border:1px solid #d6dee8;border-radius:7px;background:white}.diag-check{display:flex;gap:8px;align-items:flex-start}.diag-check input{width:16px;min-width:16px;margin:2px 0}.diag-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.diag-settings .primary{margin-top:18px}@media(max-width:700px){.diag-grid{grid-template-columns:1fr}}</style>
